 make_record('cp-290','art. 290','Crimes assimilados ao de moeda falsa','Formar cédula com fragmentos verdadeiros, suprimir sinal de inutilização ou restituir à circulação cédula recolhida para inutilização.',24,96,'Reclusão, de 2 a 8 anos, e multa.',['moeda falsa','cédula inutilizada']),
 make_record('cp-291','art. 291','Petrechos para falsificação de moeda','Fabricar, adquirir, fornecer, possuir ou guardar objeto especialmente destinado à falsificação de moeda.',24,72,'Reclusão, de 2 a 6 anos, e multa.',['petrechos','falsificação de moeda']),
 make_record('cp-292','art. 292, caput','Emissão de título ao portador sem permissão legal','Emitir sem permissão legal nota, bilhete, ficha, vale ou título com promessa de pagamento em dinheiro ao portador ou sem indicação do beneficiário.',1,6,'Detenção, de 1 a 6 meses, ou multa.',['título ao portador','emissão irregular']),
 make_record('cp-292-pu','art. 292, parágrafo único','Uso de título ao portador sem permissão legal','Receber ou utilizar como dinheiro documento abrangido pelo art. 292.',0.5,3,'Detenção, de 15 dias a 3 meses, ou multa.',['título ao portador','uso irregular'],'qualificada','cp-292'),
 make_record('cp-293','art. 293, caput','Falsificação de papéis públicos','Falsificar selo de controle tributário, papel selado, papel de emissão legal, papel de crédito público, vale postal ou documento de arrecadação ou transporte público.',24,96,'Reclusão, de 2 a 8 anos, e multa.',['papéis públicos','selo tributário']),
 make_record('cp-293-2','art. 293, § 2º','Supressão de sinal de inutilização de papel público','Suprimir, em papel público legítimo, carimbo ou sinal de inutilização para torná-lo novamente utilizável.',12,48,'Reclusão, de 1 a 4 anos, e multa.',['papéis públicos','sinal de inutilização'],'qualificada','cp-293'),
 make_record('cp-293-4','art. 293, § 4º','Uso de papel público falsificado recebido de boa-fé','Usar ou restituir à circulação, após conhecer a falsidade ou alteração, papel público falsificado ou alterado recebido de boa-fé.',6,24,'Detenção, de 6 meses a 2 anos, ou multa.',['papéis públicos','boa-fé'],'qualificada','cp-293'),
 make_record('cp-294','art. 294','Petrechos de falsificação de papéis públicos','Fabricar, adquirir, fornecer, possuir ou guardar objeto especialmente destinado à falsificação de papéis públicos.',12,36,'Reclusão, de 1 a 3 anos, e multa.',['petrechos','papéis públicos']),
 make_record('cp-296','art. 296','Falsificação de selo ou sinal público','Falsificar selo público, selo ou sinal atribuído por lei a entidade ou autoridade pública, ou sinal público de tabelião.',24,72,'Reclusão, de 2 a 6 anos, e multa.',['selo público','sinal público']),
 make_record('cp-296-pu','art. 296, § 1º, III','Uso indevido de símbolo da Administração Pública','Alterar, falsificar ou fazer uso indevido de marcas, logotipos, siglas ou símbolos utilizados ou identificadores de órgãos ou entidades da Administração Pública.',24,72,'Reclusão, de 2 a 6 anos, e multa.',['símbolo público','Administração Pública'],'qualificada','cp-296',laws=['Decreto-Lei nº 2.848/1940','Lei nº 9.983/2000']),
