 make_record('cp-299-publico','art. 299, caput, documento público','Falsidade ideológica em documento público','Omitir ou inserir declaração falsa ou diversa em documento público, para prejudicar direito, criar obrigação ou alterar a verdade sobre fato juridicamente relevante.',12,60,'Reclusão, de 1 a 5 anos, e multa.',['falsidade ideológica','documento público']),
