 make_record('cp-300-publico','art. 300, documento público','Falso reconhecimento de firma ou letra em documento público','Reconhecer como verdadeira, no exercício de função pública, firma ou letra que não o seja em documento público.',12,60,'Reclusão, de 1 a 5 anos, e multa.',['firma falsa','documento público']),
