 make_record('cp-301-1','art. 301, § 1º','Falsidade material de atestado ou certidão','Falsificar atestado ou certidão, ou alterar certidão ou atestado verdadeiro, para prova de fato que habilite alguém a obter cargo, isenção ou vantagem.',0.25,24,'Detenção, de 3 meses a 2 anos.',['certidão falsa','falsidade material'],'qualificada','cp-301'),
