 make_record('cp-303','art. 303','Reprodução ou adulteração de selo ou peça filatélica','Reproduzir ou alterar selo ou peça filatélica de valor para coleção sem anotação visível da reprodução ou alteração.',12,36,'Detenção, de 1 a 3 anos, e multa.',['selo filatélico','adulteração']),
 make_record('cp-304','art. 304','Uso de documento falso','Fazer uso de papel falsificado ou alterado referido nos arts. 297 a 302.',None,None,'Pena correspondente à falsificação ou alteração do documento utilizado.',['uso de documento falso'],observation='A pena é remissiva e depende do documento-base; mantida sem faixa numérica para evitar estimativa indevida.'),
 make_record('cp-305-publico','art. 305, documento público','Supressão de documento público','Destruir, suprimir ou ocultar, em benefício próprio ou alheio ou em prejuízo de outrem, documento público verdadeiro de que não podia dispor.',24,72,'Reclusão, de 2 a 6 anos, e multa.',['supressão de documento','documento público']),
 make_record('cp-305-particular','art. 305, documento particular','Supressão de documento particular','Destruir, suprimir ou ocultar, em benefício próprio ou alheio ou em prejuízo de outrem, documento particular verdadeiro de que não podia dispor.',12,60,'Reclusão, de 1 a 5 anos, e multa.',['supressão de documento','documento particular']),
