 make_record('cp-306-pu','art. 306, parágrafo único','Falsificação de sinal de fiscalização sanitária','Falsificar ou usar marca ou sinal empregado pela autoridade para fiscalização sanitária, autenticação, encerramento de objetos ou comprovação de formalidade legal.',12,36,'Reclusão ou detenção, de 1 a 3 anos, e multa.',['fiscalização sanitária','sinal público'],'qualificada','cp-306'),
