 make_record('cp-308','art. 308','Uso de documento de identidade alheia','Usar como próprio ou ceder a outrem passaporte, título de eleitor, caderneta de reservista ou documento de identidade alheio.',1/3,24,'Detenção, de 4 meses a 2 anos, e multa, se o fato não constitui elemento de crime mais grave.',['documento alheio','identidade']),
 make_record('cp-309','art. 309','Fraude de lei sobre estrangeiros','Usar o estrangeiro, para entrar ou permanecer no território nacional, nome que não é o seu.',12,36,'Detenção, de 1 a 3 anos, e multa.',['estrangeiro','identidade falsa']),
 make_record('cp-309-pu','art. 309, parágrafo único','Atribuição de falsa qualidade a estrangeiro','Atribuir a estrangeiro falsa qualidade para promover sua entrada em território nacional.',12,48,'Reclusão, de 1 a 4 anos, e multa.',['estrangeiro','entrada irregular'],'qualificada','cp-309',laws=['Decreto-Lei nº 2.848/1940','Lei nº 9.426/1996']),
 make_record('cp-310','art. 310','Falsidade em prejuízo da nacionalização de sociedade','Prestar-se a figurar como proprietário ou possuidor de ação, título ou valor pertencente a estrangeiro quando a lei lhe veda essa propriedade ou posse.',6,36,'Detenção, de 6 meses a 3 anos, e multa.',['estrangeiro','sociedade','falsidade'],laws=['Decreto-Lei nº 2.848/1940','Lei nº 9.426/1996']),
