 make_record('cp-311-3','art. 311, § 3º','Comércio de veículo com sinal identificador adulterado','Praticar em atividade comercial ou industrial as condutas de adquirir, transportar, ocultar, manter em depósito, fabricar, fornecer ou possuir objeto de falsificação, ou utilizar veículo com sinal adulterado.',48,96,'Reclusão, de 4 a 8 anos, e multa.',['veículo','sinal identificador','comércio'],'qualificada','cp-311',laws=['Decreto-Lei nº 2.848/1940','Lei nº 14.562/2023']),
